return ['domain'=>'simple-ldap-login','plural-forms'=>'nplurals=1; plural=0;','language'=>'zh_TW','project-id-version'=>'Simple LDAP Login 2.0.0','pot-creation-date'=>'2026-10-30T15:26:17+00:00','po-revision-date'=>'2026-10-30T15:26:17+00:00','x-generator'=>'WP-CLI 2.12.0','messages'=>['Simple LDAP Login'=>'Simple LDAP Login','https://github.com/clifgriffin/simple-ldap-login'=>'https://github.com/clifgriffin/simple-ldap-login','Connect WordPress accounts to Active Directory or OpenLDAP.'=>'將 WordPress 帳戶連接到 Active Directory 或 OpenLDAP。','Clif Griffin Development Inc.'=>'Clif Griffin Development Inc.','https://clifgriffin.com'=>'https://clifgriffin.com','User data'=>'用戶數據','Single sign-on'=>'單一登入','Custom user fields'=>'自定義用戶字段','Copy LDAP attributes to WordPress user meta fields.'=>'將 LDAP 屬性複製到 WordPress 用戶元數據字段。','Field mappings'=>'字段映射','One mapping per line: LDAP attribute:WordPress meta key:type. Example: %1$s. Types: %2$s or %3$s.'=>'每行一個映射：LDAP 屬性：WordPress 元數據鍵：類型。範例：%1$s。類型：%2$s 或 %3$s。','Custom field storage'=>'自定義字段存儲','Leave the defaults unless your integration uses different user meta keys.'=>'除非您的集成使用不同的用戶元數據鍵，否則保留默認值。','LDAP value suffix'=>'LDAP 值後綴','Stores the LDAP value, such as phone_ldap.'=>'存儲 LDAP 值，例如 phone_ldap。','WordPress value suffix'=>'WordPress 值後綴','Stores the editable WordPress value, such as phone_wp.'=>'存儲可編輯的 WordPress 值，例如 phone_wp。','Single sign-on (SSO)'=>'單一登入 (SSO)','Your web server must authenticate users and set REMOTE_USER. Never copy a browser header into REMOTE_USER or allow access that bypasses server authentication. Set the LDAP search account on Connection.'=>'您的網絡伺服器必須驗證用戶並設置 REMOTE_USER。切勿將瀏覽器標頭複製到 REMOTE_USER 或允許繞過伺服器身份驗證的訪問。請在連接上設置 LDAP 搜索帳戶。','Enable automatic login after web server authentication.'=>'在網絡伺服器身份驗證後啟用自動登錄。','Web server authentication'=>'網絡伺服器身份驗證','REMOTE_USER is present.'=>'REMOTE_USER 存在。','REMOTE_USER is missing. Check the web server configuration.'=>'REMOTE_USER 缺失。檢查網絡伺服器配置。','The update was stopped. Activate Simple LDAP Login Pro to restore LDAP login.'=>'更新已停止。啟用 Simple LDAP Login Pro 以恢復 LDAP 登入。','Update blocked: This package does not include all Pro files. To install Free, deactivate the plugin first. Your installed files and settings are unchanged.'=>'更新被阻止：此套件不包含所有 Pro 檔案。要安裝免費版本，請先停用插件。您已安裝的檔案和設定保持不變。','WordPress could not reactivate the plugin.'=>'WordPress 無法重新啟用插件。','Simple LDAP Login needs PHP 8.1 or later.'=>'Simple LDAP Login 需要 PHP 8.1 或更高版本。','Plugin files are missing. Reinstall Simple LDAP Login from the release ZIP.'=>'插件文件缺失。從發行 ZIP 重新安裝 Simple LDAP Login。','You do not have permission to change these settings.'=>'您沒有權限更改這些設置。','The settings scope has changed. Open the settings page and try again.'=>'設置範圍已更改。打開設置頁面並重試。','You do not have permission to view these settings.'=>'您沒有權限查看這些設置。','Network settings'=>'網絡設置','Site settings'=>'站點設置','LDAP login settings'=>'LDAP 登錄設置','Connect to LDAP, then test a login before enabling authentication.'=>'連接到 LDAP，然後在啟用身份驗證之前測試登錄。','LDAP login and SSO are disabled by SLL_DISABLE_LDAP in wp-config.php.'=>'LDAP 登錄和 SSO 被 wp-config.php 中的 SLL_DISABLE_LDAP 禁用。','Your saved settings use SSO or custom user fields. Install Simple LDAP Login Pro to use these features. Your settings are kept.'=>'您的已保存設置使用 SSO 或自定義用戶字段。安裝 Simple LDAP Login Pro 以使用這些功能。您的設置已保留。','The saved LDAP search password cannot be read. Enter it again on the Connection tab.'=>'無法讀取已保存的 LDAP 搜索密碼。請在連接選項卡上重新輸入。','PHP LDAP is missing. Ask your host to install it before enabling LDAP login.'=>'缺少 PHP LDAP。請向您的主機請求安裝它，然後再啟用 LDAP 登入。','LDAP passwords are sent without encryption. Use StartTLS or LDAPS if your server supports it.'=>'LDAP 密碼以未加密的方式發送。如果您的伺服器支持，請使用 StartTLS 或 LDAPS。','Save settings'=>'保存設置','Settings on other tabs are kept.'=>'其他選項卡上的設置將被保留。','LDAP connection'=>'LDAP 連接','LDAP login'=>'LDAP 登入','Enable LDAP authentication.'=>'啟用 LDAP 認證。','Directory type'=>'目錄類型','Active Directory'=>'Active Directory','OpenLDAP / other LDAP directory'=>'OpenLDAP / 其他 LDAP 目錄','LDAP servers'=>'LDAP 伺服器','One hostname or IP address per line. Servers are tried in order.'=>'每行一個主機名或 IP 地址。伺服器將按順序嘗試。','Base DN'=>'基本 DN','Where to search for users. Example: DC=example,DC=org.'=>'用於搜索用戶的位置。示例：DC=example,DC=org。','Username suffix'=>'用戶名後綴','Added to usernames without a domain. Example: @example.org.'=>'添加到沒有域的用戶名。示例：@example.org。','Windows domain'=>'Windows 域','Short domain name, such as EXAMPLE. Takes priority over the username suffix.'=>'短域名，例如 EXAMPLE。優先於用戶名後綴。','Connection security'=>'連接安全性','TLS requires a trusted server certificate.'=>'TLS 需要受信任的伺服器證書。','StartTLS (recommended)'=>'StartTLS（推薦）','LDAPS'=>'LDAPS','Unencrypted LDAP'=>'未加密的 LDAP','Unencrypted LDAP requires permission on the Advanced tab.'=>'未加密的 LDAP 需要在高級選項卡上授權。','Port'=>'端口','389 for StartTLS; 636 for LDAPS.'=>'StartTLS 使用 389；LDAPS 使用 636。','Search subfolders'=>'搜索子文件夾','Search all organizational units below the Base DN.'=>'搜索基本 DN 下面的所有組織單位。','LDAP search account'=>'LDAP 搜索帳戶','An LDAP account with read access to users and groups.'=>'具有用戶和群組讀取權限的 LDAP 帳戶。','Search account'=>'搜索帳戶','LDAP bind DN or account name.'=>'LDAP 綁定 DN 或帳戶名稱。','Search account password'=>'搜索帳戶密碼','Leave blank to keep the saved password.'=>'留空以保留已保存的密碼。','Login rules'=>'登入規則','Require LDAP passwords'=>'要求 LDAP 密碼','Block WordPress passwords except for recovery access.'=>'阻止 WordPress 密碼，僅限於恢復訪問。','Local recovery access'=>'本地恢復訪問','Selected administrators'=>'選定的管理員','All super administrators (legacy)'=>'所有超級管理員（舊版）','All administrators (legacy)'=>'所有管理員（舊版）','Off'=>'關閉','Choose who can use a WordPress password when LDAP passwords are required.'=>'選擇在要求 LDAP 密碼時可以使用 WordPress 密碼的用戶。','Automatic account creation'=>'自動帳戶創建','Create a WordPress account on the first successful LDAP login.'=>'在第一次成功的 LDAP 登入時創建 WordPress 帳戶。','Default role'=>'默認角色','For new accounts only.'=>'僅適用於新帳戶。','Required groups'=>'所需群組','One group name per line. Users must belong to at least one. Leave blank to allow all LDAP users.'=>'每行一個群組名稱。用戶必須至少屬於一個。留空以允許所有 LDAP 用戶。','Recovery accounts'=>'恢復帳戶','For Selected administrators only. Use separate local accounts with WordPress passwords. Hold Ctrl or Command to select multiple accounts.'=>'僅適用於選定的管理員。使用單獨的本地帳戶和 WordPress 密碼。按住 Ctrl 或 Command 以選擇多個帳戶。','Connection options'=>'連接選項','Change these only if the default values do not work with your directory.'=>'僅在默認值無法與您的目錄配合使用時更改這些設置。','LDAP timeout (seconds)'=>'LDAP 超時（秒）','Maximum wait for an LDAP operation. Default: 5 seconds.'=>'LDAP 操作的最大等待時間。默認：5 秒。','Login attribute'=>'登入屬性','Attribute used to find users. Default: uid.'=>'用於查找用戶的屬性。默認：uid。','Allow unencrypted LDAP'=>'允許未加密的 LDAP','Allow passwords to be sent without encryption.'=>'允許以未加密的方式發送密碼。','Group search'=>'群組搜尋','Group base DN'=>'群組基本 DN','Leave blank to use the user Base DN.'=>'留空以使用使用者基本 DN。','Group name attribute'=>'群組名稱屬性','Default: cn.'=>'預設：cn。','Group member attribute'=>'群組成員屬性','Default: memberUid. Use member or uniqueMember if groups store user DNs.'=>'預設：memberUid。如果群組儲存使用者 DN，請使用 member 或 uniqueMember。','Profile attributes'=>'個人資料屬性','LDAP attributes copied to new WordPress accounts.'=>'複製到新 WordPress 帳戶的 LDAP 屬性。','First name attribute'=>'名字屬性','Last name attribute'=>'姓氏屬性','Email attribute'=>'電子郵件屬性','Website attribute'=>'網站屬性','Data retention'=>'資料保留','Delete settings when removing the plugin'=>'移除插件時刪除設定','Delete saved settings and LDAP credentials when WordPress deletes the plugin. Keep user accounts.'=>'當 WordPress 刪除插件時，刪除已儲存的設定和 LDAP 憑證。保留使用者帳戶。','Test LDAP login'=>'測試 LDAP 登入','Save your settings, then run both tests. Keep this administrator session open.'=>'儲存您的設定，然後運行兩個測試。保持此管理員會話開啟。','Tests check the connection, password, and required groups. They do not create accounts or sign users in.'=>'測試檢查連接、密碼和所需的群組。它們不會創建帳戶或登入使用者。','After both tests pass, enable LDAP and try logging in from another browser.'=>'在兩個測試通過後，啟用 LDAP 並嘗試從另一個瀏覽器登入。','Recovery'=>'恢復','If you are locked out, rename the simple-ldap-login folder using your hosting file manager. Log in with a WordPress administrator password, then restore the folder and correct the settings.'=>'如果您被鎖定，請使用您的主機檔案管理器重新命名 simple-ldap-login 資料夾。使用 WordPress 管理員密碼登入，然後恢復資料夾並修正設定。','For certificate errors, ask your host to configure the trusted LDAP certificate authority.'=>'對於證書錯誤，請要求您的主機配置受信任的 LDAP 證書授權。','LDAP tests'=>'LDAP 測試','Tests use saved settings.'=>'測試使用已儲存的設定。','1. Test connection'=>'1. 測試連接','Connect to LDAP and test the search account, if set.'=>'連接到 LDAP 並測試搜尋帳戶（如果已設置）。','Test connection'=>'測試連接','2. Test login'=>'2. 測試登入','Check an LDAP username, password, and group membership.'=>'檢查 LDAP 使用者名稱、密碼和群組成員資格。','LDAP username'=>'LDAP 使用者名稱','LDAP password'=>'LDAP 密碼','Settings saved.'=>'設定已儲存。','Connection test passed.'=>'連接測試通過。','Cannot connect to LDAP. Check the server, port, TLS certificate, and search account.'=>'無法連接到 LDAP。檢查伺服器、端口、TLS 證書和搜尋帳戶。','LDAP login test passed. No account was created.'=>'LDAP 登入測試通過。未創建帳戶。','LDAP login test failed. Check the username, password, and required groups.'=>'LDAP 登入測試失敗。檢查使用者名稱、密碼和所需的群組。','Could not save settings. Check the values and try again.'=>'無法儲存設定。檢查值並重試。','Connection'=>'連接','Access'=>'訪問','Advanced'=>'進階','Troubleshooting'=>'故障排除','Your LDAP login is valid, but you need a WordPress account. Contact your site administrator.'=>'您的 LDAP 登入有效，但您需要一個 WordPress 帳戶。請聯繫您的網站管理員。','Your LDAP username is not a valid WordPress username. Contact your site administrator.'=>'您的 LDAP 使用者名稱不是有效的 WordPress 使用者名稱。請聯繫您的網站管理員。','The default WordPress role is not available. Contact your site administrator.'=>'預設的 WordPress 角色不可用。請聯繫您的網站管理員。','Could not create your WordPress account. Contact your site administrator.'=>'無法創建您的 WordPress 帳戶。請聯繫您的網站管理員。','Use your WordPress password for this recovery account.'=>'使用您的 WordPress 密碼作為此恢復帳戶。','LDAP login failed. Check your username and password or contact your site administrator.'=>'LDAP 登入失敗。檢查您的使用者名稱和密碼或聯繫您的網站管理員。','Your account is not allowed to log in to this site.'=>'您的帳戶不允許登錄此網站。','LDAP login is unavailable. Contact your site administrator.'=>'LDAP 登錄不可用。請聯繫您的網站管理員。','PHP OpenSSL is required to save the LDAP search password.'=>'需要 PHP OpenSSL 來保存 LDAP 搜索密碼。','Could not read or save the LDAP search password. Enter it again. If this continues, ask your host to check OpenSSL and the encryption key.'=>'無法讀取或保存 LDAP 搜索密碼。請重新輸入。如果問題持續，請要求您的主機檢查 OpenSSL 和加密密鑰。','Select a recovery account on the Access tab, or turn local recovery access Off.'=>'在訪問選項卡上選擇一個恢復帳戶，或將本地恢復訪問關閉。','Enable Allow unencrypted LDAP on the Advanced tab, or choose StartTLS or LDAPS.'=>'在高級選項卡上啟用允許未加密的 LDAP，或選擇 StartTLS 或 LDAPS。','A custom field mapping uses a protected or invalid WordPress user meta key.'=>'自定義字段映射使用了受保護或無效的 WordPress 用戶元數據鍵。','Enter a Base DN and at least one LDAP server before enabling LDAP login.'=>'在啟用 LDAP 登錄之前，請輸入基本 DN 和至少一個 LDAP 伺服器。','WordPress could not save the settings. Try again.'=>'WordPress 無法保存設置。請重試。','LDAP protocol version'=>'LDAP 協議版本','LDAP timeout'=>'LDAP 超時','Check the submitted settings. No changes were saved.'=>'檢查提交的設置。未保存任何更改。','Check %s. No changes were saved.'=>'檢查 %s。未保存任何更改。']];